<script setup>
const props=defineProps({modelValue:Object});const emit=defineEmits(['update:modelValue']);const labels=['周日','周一','周二','周三','周四','周五','周六'];
function toggle(day,phaseIndex=null){const r=JSON.parse(JSON.stringify(props.modelValue));const target=phaseIndex===null?r:r.phases[phaseIndex];const days=new Set(target.weekdays||[]);days.has(day)?days.delete(day):days.add(day);target.weekdays=[...days].sort();emit('update:modelValue',r);}
function addPhase(){emit('update:modelValue',{...props.modelValue,phases:[...(props.modelValue.phases||[]),{from:'',weekdays:[...(props.modelValue.weekdays||[])]}]});}
function date(index,value){const r=JSON.parse(JSON.stringify(props.modelValue));r.phases[index].from=value;emit('update:modelValue',r);}
function remove(index){emit('update:modelValue',{...props.modelValue,phases:props.modelValue.phases.filter((_,i)=>i!==index)});}
</script>
<template><section class="weekly-editor"><h4>每周播出日（可多选）</h4><div class="weekday-choices"><label v-for="day in [1,2,3,4,5,6,0]" :key="day"><input type="checkbox" :checked="modelValue.weekdays?.includes(day)" @change="toggle(day)">{{labels[day]}}</label></div><p v-if="!Object.hasOwn(modelValue,'weekdays')">旧排期：每 {{modelValue.intervalDays||7}} 天更新。选择周几后改为按周排播。</p><div v-for="(phase,index) in modelValue.phases||[]" class="phase"><label>调整生效日期<input type="date" :value="phase.from" :min="modelValue.premiere" @input="date(index,$event.target.value)" required></label><div class="weekday-choices"><label v-for="day in [1,2,3,4,5,6,0]"><input type="checkbox" :checked="phase.weekdays.includes(day)" @change="toggle(day,index)">{{labels[day]}}</label></div><button type="button" @click="remove(index)">移除此阶段</button></div><button type="button" :disabled="!modelValue.weekdays?.length" @click="addPhase">＋ 从某日起更换播出日</button><p>例如先选周四、周五，再新增一个生效日期，改选周四、周日。</p></section></template>
<style scoped>.weekly-editor{margin:18px 0}.weekly-editor h4{font-size:14px;font-weight:500;margin:0 0 12px}.weekday-choices{display:flex;flex-wrap:wrap;gap:12px 18px}.weekday-choices label{display:inline-flex;align-items:center;gap:6px;font-size:13px}.weekly-editor input[type=checkbox]{width:auto}.weekly-editor p{font-size:12px;color:#7d857d;line-height:1.6}.phase{padding:12px 0;margin:14px 0;border-top:1px solid #dde3d8}.phase>label{display:flex;flex-direction:column;gap:6px;font-size:13px;margin-bottom:12px}.phase input[type=date]{font:inherit;padding:8px;border:1px solid #d9ded7;border-radius:7px;width:100%;box-sizing:border-box}button{font:inherit;font-size:12px;margin-top:12px;padding:7px 12px;background:white;border:1px solid #d9ded7;border-radius:7px;color:#303b35;cursor:pointer}button:disabled{opacity:.4}</style>
